53	pub fn bind_keys(cx: &mut App) {
54	    let context = Some(CONTEXT);
55	    cx.bind_keys([
56	        KeyBinding::new("down", SelectNext, context),
57	        KeyBinding::new("up", SelectPrevious, context),
58	        KeyBinding::new("home", SelectFirst, context),
59	        KeyBinding::new("end", SelectLast, context),
60	        KeyBinding::new("pagedown", SelectPageDown, context),
61	        KeyBinding::new("pageup", SelectPageUp, context),
62	        KeyBinding::new("enter", OpenSelected, context),
63	        KeyBinding::new("right", OpenSelected, context),
64	        KeyBinding::new("backspace", GoUp, context),
65	        KeyBinding::new("left", GoUp, context),
66	        #[cfg(target_os = "macos")]
67	        KeyBinding::new("cmd-up", GoUp, context),
68	        #[cfg(not(target_os = "macos"))]
69	        KeyBinding::new("alt-up", GoUp, context),
70	        #[cfg(target_os = "macos")]
71	        KeyBinding::new("cmd-shift-h", GoHome, context),
72	        #[cfg(not(target_os = "macos"))]
73	        KeyBinding::new("alt-home", GoHome, context),
74	        #[cfg(target_os = "macos")]
75	        KeyBinding::new("cmd-enter", ChooseFolderAction, context),
76	        #[cfg(not(target_os = "macos"))]
77	        KeyBinding::new("ctrl-enter", ChooseFolderAction, context),
78	        #[cfg(target_os = "macos")]
79	        KeyBinding::new("cmd-shift-.", ToggleHidden, context),
80	        #[cfg(not(target_os = "macos"))]
81	        KeyBinding::new("ctrl-h", ToggleHidden, context),
82	        #[cfg(target_os = "macos")]
83	        KeyBinding::new("cmd-shift-n", NewFolderAction, context),
84	        #[cfg(not(target_os = "macos"))]
85	        KeyBinding::new("ctrl-shift-n", NewFolderAction, context),
86	    ]);
87	}
