89	/// The index `step` folders on from `selected` among `count`, stopping at the
90	/// ends; with nothing selected, stepping forward starts at the first and
91	/// back at the last.
92	pub fn step_selection(selected: Option<usize>, count: usize, step: isize) -> Option<usize> {
93	    if count == 0 {
94	        return None;
95	    }
96	    let last = count as isize - 1;
97	    let next = match selected {
98	        None if step < 0 => last,
99	        None => 0,
100	        Some(ix) => (ix as isize + step).clamp(0, last),
101	    };
102	    Some(next as usize)
103	}
104	
105	/// The first of `folders` whose name starts with `typed`, ignoring case.
106	pub fn type_ahead_match(folders: &[PathBuf], typed: &str) -> Option<usize> {
107	    let typed = typed.to_lowercase();
108	    folders.iter().position(|folder| {
109	        folder
110	            .file_name()
111	            .is_some_and(|name| name.to_string_lossy().to_lowercase().starts_with(&typed))
112	    })
113	}
114	
115	/// Why `name` can't be a new folder in `dir`, if it can't.
116	pub fn new_folder_problem(dir: &Path, name: &str) -> Option<String> {
117	    let name = name.trim();
118	    if name.is_empty() {
119	        Some("Give the folder a name".into())
120	    } else if name.contains(['/', '\\']) {
121	        Some("A name can't contain a slash".into())
122	    } else if name == "." || name == ".." {
123	        Some("A name can't be . or ..".into())
124	    } else if dir.join(name).symlink_metadata().is_ok() {
125	        Some(format!("{name} is already here"))
126	    } else {
127	        None
128	    }
129	}
130	
131	/// Creates the folder `name` in `dir`, returning it.
132	pub fn create_folder(dir: &Path, name: &str) -> Result<PathBuf, String> {
133	    if let Some(problem) = new_folder_problem(dir, name) {
134	        return Err(problem);
135	    }
136	    let folder = dir.join(name.trim());
137	    std::fs::create_dir(&folder)
138	        .map_err(|err| format!("Couldn't create {}: {err}", folder.display()))?;
139	    Ok(folder)
140	}
141	
142	/// The row for naming a new folder, while it is open.
143	struct NewFolder {
144	    input: Entity<InputState>,
145	    /// Why the folder couldn't be created, when it couldn't.
146	    error: Option<SharedString>,
147	    _subscription: Subscription,
148	}
149	
150	/// Emitted with the folder chosen.
151	pub struct ChooseFolder(pub PathBuf);
152	
153	/// Emitted when the browser is left without choosing.
154	pub struct CancelFolder;
155	
156	/// The folders in `dir`, sorted by name ignoring case, leaving out those whose
157	/// names start with a dot unless `show_hidden`.
158	pub fn list_folders(dir: &Path, show_hidden: bool) -> std::io::Result<Vec<PathBuf>> {
159	    let mut folders: Vec<PathBuf> = std::fs::read_dir(dir)?
160	        .filter_map(|entry| entry.ok())
161	        .filter(|entry| {
162	            // Following links, so a link to a folder counts as one.
163	            std::fs::metadata(entry.path()).is_ok_and(|meta| meta.is_dir())
164	        })
165	        .map(|entry| entry.path())
166	        .filter(|path| {
167	            show_hidden
168	                || !path
169	                    .file_name()
170	                    .is_some_and(|name| name.to_string_lossy().starts_with('.'))
171	        })
172	        .collect();
173	    folders.sort_by_key(|path| {
174	        path.file_name()
175	            .map(|name| name.to_string_lossy().to_lowercase())
176	            .unwrap_or_default()
177	    });
178	    Ok(folders)
179	}
180	
181	/// Each folder along `dir`'s path, from the top of the file system down to
182	/// `dir`, with the name it shows as in the breadcrumb.
183	pub fn crumbs(dir: &Path) -> Vec<(String, PathBuf)> {
184	    dir.ancestors()
185	        .collect::<Vec<_>>()
186	        .into_iter()
187	        .rev()
188	        .map(|path| {
189	            let name = path
190	                .file_name()
191	                .map(|name| name.to_string_lossy().into_owned())
192	                .unwrap_or_else(|| path.display().to_string());
193	            (name, path.to_path_buf())
194	        })
195	        .collect()
196	}
