198	pub struct FolderBrowser {
199	    title: SharedString,
200	    dir: PathBuf,
201	    show_hidden: bool,
202	    /// The current folder's folders, or why they couldn't be read.
203	    folders: Result<Vec<PathBuf>, SharedString>,
204	    selected: Option<usize>,
205	    scroll: ScrollHandle,
206	    new_folder: Option<NewFolder>,
207	    /// The list of folders, which has focus when the browser opens.
208	    focus_handle: FocusHandle,
209	    /// What has been typed to select a folder by name, and when last.
210	    typed: String,
211	    typed_at: Option<Instant>,
212	}
