223	impl FolderBrowser {
224	    /// A browser titled `title`, starting in `dir`, or the home folder when
225	    /// `dir` isn't a folder.
226	    pub fn new(title: impl Into<SharedString>, dir: PathBuf, cx: &mut Context<Self>) -> Self {
227	        let dir = if dir.is_dir() { dir } else { home() };
228	        let mut this = Self {
229	            focus_handle: cx.focus_handle().tab_stop(true),
230	            typed: String::new(),
231	            typed_at: None,
232	            title: title.into(),
233	            dir: PathBuf::new(),
234	            show_hidden: false,
235	            folders: Ok(Vec::new()),
236	            selected: None,
237	            scroll: ScrollHandle::new(),
238	            new_folder: None,
239	        };
240	        this.load(dir);
241	        this
242	    }
243	
244	    #[cfg(test)]
245	    pub fn selected(&self) -> Option<usize> {
246	        self.selected
247	    }
248	
249	    #[cfg(test)]
250	    pub fn show_hidden(&self) -> bool {
251	        self.show_hidden
252	    }
253	
254	    #[cfg(test)]
255	    pub fn dir(&self) -> &Path {
256	        &self.dir
257	    }
