259	    /// What "Choose" chooses: the selected folder, or the current one.
260	    pub fn choice(&self) -> PathBuf {
261	        self.selected
262	            .and_then(|ix| self.folders.as_ref().ok()?.get(ix).cloned())
263	            .unwrap_or_else(|| self.dir.clone())
264	    }
265	
266	    fn load(&mut self, dir: PathBuf) {
267	        self.folders = list_folders(&dir, self.show_hidden)
268	            .map_err(|err| format!("Couldn't read {}: {err}", dir.display()).into());
269	        self.dir = dir;
270	        self.selected = None;
271	        self.new_folder = None;
272	        self.scroll.set_offset(point(px(0.), px(0.)));
273	    }
274	
275	    /// Opens the row for naming a new folder in the current one, its name
276	    /// field focused.
277	    pub fn open_new_folder(&mut self, window: &mut Window, cx: &mut Context<Self>) {
278	        let input = cx.new(|cx| InputState::new(window, cx).placeholder("Folder name"));
279	        let subscription = cx.subscribe_in(
280	            &input,
281	            window,
282	            |this, _, event: &InputEvent, window, cx| match event {
283	                InputEvent::PressEnter { .. } => this.create_new_folder(window, cx),
284	                InputEvent::Change => {
285	                    if let Some(row) = &mut this.new_folder {
286	                        row.error = None;
287	                    }
288	                    cx.notify();
289	                }
290	                _ => {}
291	            },
292	        );
293	        input.update(cx, |input, cx| input.focus(window, cx));
294	        self.new_folder = Some(NewFolder {
295	            input,
296	            error: None,
297	            _subscription: subscription,
298	        });
299	        cx.notify();
300	    }
301	
302	    #[cfg(test)]
303	    pub fn set_new_folder_name(&mut self, name: &str, window: &mut Window, cx: &mut Context<Self>) {
304	        if let Some(row) = &self.new_folder {
305	            row.input.update(cx, |input, cx| {
306	                input.set_value(name.to_string(), window, cx)
307	            });
308	        }
309	    }
310	
311	    #[cfg(test)]
312	    pub fn new_folder_open(&self) -> bool {
313	        self.new_folder.is_some()
314	    }
315	
316	    /// <Escape>: closes the new folder row, or, without it open, leaves the
317	    /// browser without choosing.
318	    fn escape(&mut self, window: &mut Window, cx: &mut Context<Self>) {
319	        if self.new_folder.is_some() {
320	            self.close_new_folder(window, cx);
321	        } else {
322	            cx.emit(CancelFolder);
323	        }
324	    }
325	
326	    /// Closes the new folder row, handing the keyboard back to the list.
327	    fn close_new_folder(&mut self, window: &mut Window, cx: &mut Context<Self>) {
328	        self.new_folder = None;
329	        self.focus_handle.focus(window, cx);
330	        cx.notify();
331	    }
332	
333	    /// Creates the folder named in the row, then selects it; or says why it
334	    /// couldn't be, keeping the row open.
335	    pub fn create_new_folder(&mut self, window: &mut Window, cx: &mut Context<Self>) {
336	        let Some(row) = &mut self.new_folder else {
337	            return;
338	        };
339	        let name = row.input.read(cx).value().to_string();
340	        match create_folder(&self.dir, &name) {
341	            Err(err) => {
342	                row.error = Some(err.into());
343	                cx.notify();
344	            }
345	            Ok(folder) => {
346	                self.load(self.dir.clone());
347	                self.focus_handle.focus(window, cx);
348	                self.selected = self
349	                    .folders
350	                    .as_ref()
351	                    .ok()
352	                    .and_then(|folders| folders.iter().position(|path| *path == folder));
353	                if let Some(ix) = self.selected {
354	                    self.scroll.scroll_to_item(ix);
355	                }
356	                cx.notify();
357	            }
358	        }
359	    }
360	
361	    /// Goes to `dir`.
362	    pub fn go(&mut self, dir: PathBuf, cx: &mut Context<Self>) {
363	        self.load(dir);
364	        cx.notify();
365	    }
366	
367	    /// Goes up to the folder holding this one, selecting the folder left.
368	    fn up(&mut self, cx: &mut Context<Self>) {
369	        let Some(parent) = self.dir.parent().map(Path::to_path_buf) else {
370	            return;
371	        };
372	        let left = self.dir.clone();
373	        self.go(parent, cx);
374	        self.select_path(&left);
375	    }
376	
377	    fn set_show_hidden(&mut self, show: bool, cx: &mut Context<Self>) {
378	        let selected = self
379	            .selected
380	            .and_then(|ix| self.folders.as_ref().ok()?.get(ix).cloned());
381	        self.show_hidden = show;
382	        self.load(self.dir.clone());
383	        if let Some(selected) = selected {
384	            self.select_path(&selected);
385	        }
386	        cx.notify();
387	    }
388	
389	    /// Selects `path` if it is listed, scrolling it into view.
390	    fn select_path(&mut self, path: &Path) {
391	        let ix = self
392	            .folders
393	            .as_ref()
394	            .ok()
395	            .and_then(|folders| folders.iter().position(|folder| folder == path));
396	        if ix.is_some() {
397	            self.select(ix);
398	        }
399	    }
400	
401	    /// Selects the folder at `ix`, scrolling it into view.
402	    fn select(&mut self, ix: Option<usize>) {
403	        self.selected = ix;
404	        if let Some(ix) = ix {
405	            self.scroll.scroll_to_item(ix);
406	        }
407	    }
408	
409	    fn folder_count(&self) -> usize {
410	        self.folders.as_ref().map_or(0, Vec::len)
411	    }
412	
413	    /// Selects the first folder, or with `last` the last one.
414	    fn select_end(&mut self, last: bool, cx: &mut Context<Self>) {
415	        let count = self.folder_count();
416	        if count > 0 {
417	            self.select(Some(if last { count - 1 } else { 0 }));
418	            cx.notify();
419	        }
420	    }
421	
422	    /// Moves the selection `step` folders, stopping at the ends.
423	    fn step(&mut self, step: isize, cx: &mut Context<Self>) {
424	        self.select(step_selection(self.selected, self.folder_count(), step));
425	        cx.notify();
426	    }
427	
428	    /// Goes into the selected folder, or, with none selected, chooses the
429	    /// current one.
430	    fn open_selected(&mut self, cx: &mut Context<Self>) {
431	        match self.selected {
432	            Some(ix) => self.click_folder(ix, 2, cx),
433	            None => cx.emit(ChooseFolder(self.dir.clone())),
434	        }
435	    }
436	
437	    /// Typing selects the first folder whose name starts with what has been
438	    /// typed, building up while the keys come quickly.
439	    fn type_ahead(&mut self, event: &KeyDownEvent, cx: &mut Context<Self>) {
440	        let keystroke = &event.keystroke;
441	        let modifiers = &keystroke.modifiers;
442	        if self.new_folder.is_some()
443	            || modifiers.control
444	            || modifiers.alt
445	            || modifiers.platform
446	            || modifiers.function
447	        {
448	            return;
449	        }
450	        let Some(typed) = keystroke
451	            .key_char
452	            .as_deref()
453	            .filter(|typed| !typed.is_empty() && typed.chars().all(|c| !c.is_control()))
454	        else {
455	            return;
456	        };
457	        let fresh = self
458	            .typed_at
459	            .is_none_or(|at| at.elapsed() >= TYPE_AHEAD_PAUSE);
460	        if fresh {
461	            self.typed.clear();
462	        }
463	        // A space only continues a name, rather than starting one.
464	        if self.typed.is_empty() && typed.trim().is_empty() {
465	            return;
466	        }
467	        self.typed.push_str(typed);
468	        self.typed_at = Some(Instant::now());
469	        if let Some(ix) = self
470	            .folders
471	            .as_ref()
472	            .ok()
473	            .and_then(|folders| type_ahead_match(folders, &self.typed))
474	        {
475	            self.select(Some(ix));
476	        }
477	        cx.stop_propagation();
478	        cx.notify();
479	    }
480	
481	    /// A click on the folder at `ix`: the first selects it, the second goes
482	    /// into it.
483	    pub fn click_folder(&mut self, ix: usize, clicks: usize, cx: &mut Context<Self>) {
484	        let Some(folder) = self.folders.as_ref().ok().and_then(|f| f.get(ix)).cloned() else {
485	            return;
486	        };
487	        if clicks >= 2 {
488	            self.go(folder, cx);
489	        } else {
490	            self.selected = Some(ix);
491	            cx.notify();
492	        }
493	    }
494	
495	    fn render_bar(&self, cx: &mut Context<Self>) -> impl IntoElement {
496	        let theme = cx.theme();
497	        let crumbs = crumbs(&self.dir);
498	        let last = crumbs.len().saturating_sub(1);
499	        h_flex()
500	            .gap_1()
501	            .px_3()
502	            .py_2()
503	            .border_b_1()
504	            .border_color(theme.border)
505	            .child(
506	                Button::new("folder-up")
507	                    .ghost()
508	                    .small()
509	                    .icon(IconName::CornerLeftUp)
510	                    .tooltip_with_action(
511	                        "Go up to the folder holding this one",
512	                        &GoUp,
513	                        Some(CONTEXT),
514	                    )
515	                    .disabled(self.dir.parent().is_none())
516	                    .on_click(cx.listener(|this, _, _, cx| this.up(cx))),
517	            )
518	            .child(
519	                Button::new("folder-home")
520	                    .ghost()
521	                    .small()
522	                    .icon(IconName::House)
523	                    .tooltip_with_action("Go to your home folder", &GoHome, Some(CONTEXT))
524	                    .on_click(cx.listener(|this, _, _, cx| this.go(home(), cx))),
525	            )
526	            .child(
527	                Button::new("folder-new")
528	                    .ghost()
529	                    .small()
530	                    .icon(IconName::FolderPlus)
531	                    .label("New Folder")
532	                    .tooltip_with_action(
533	                        "Create a folder in this one",
534	                        &NewFolderAction,
535	                        Some(CONTEXT),
536	                    )
537	                    .disabled(self.folders.is_err())
538	                    .on_click(cx.listener(|this, _, window, cx| this.open_new_folder(window, cx))),
539	            )
540	            .child(
541	                h_flex()
542	                    .id("folder-crumbs")
543	                    .flex_1()
544	                    .min_w_0()
545	                    .overflow_x_hidden()
546	                    .gap_0p5()
547	                    .children(crumbs.into_iter().enumerate().map(|(ix, (name, path))| {
548	                        // The top of the file system is already a slash.
549	                        let separator =
550	                            (ix >= 2).then(|| div().text_color(theme.muted_foreground).child("/"));
551	                        let crumb = Button::new(("folder-crumb", ix))
552	                            .ghost()
553	                            .xsmall()
554	                            .label(name)
555	                            .selected(ix == last)
556	                            .on_click(cx.listener(move |this, _, _, cx| this.go(path.clone(), cx)));
557	                        h_flex().flex_none().children(separator).child(crumb)
558	                    })),
559	            )
560	            .child(
561	                checkbox("folder-show-hidden", "Show hidden")
562	                    .checked(self.show_hidden)
563	                    .on_click(cx.listener(|this, checked: &bool, _, cx| {
564	                        this.set_show_hidden(*checked, cx)
565	                    })),
566	            )
567	    }
568	
569	    fn render_folders(&self, cx: &mut Context<Self>) -> AnyElement {
570	        let theme = cx.theme();
571	        let folders = match &self.folders {
572	            Err(err) => {
573	                return div()
574	                    .flex_1()
575	                    .p_4()
576	                    .text_color(theme.danger)
577	                    .child(err.clone())
578	                    .into_any_element();
579	            }
580	            Ok(folders) if folders.is_empty() && self.new_folder.is_none() => {
581	                return div()
582	                    .flex_1()
583	                    .p_4()
584	                    .text_color(theme.muted_foreground)
585	                    .child("No folders here")
586	                    .into_any_element();
587	            }
588	            Ok(folders) => folders,
589	        };
590	        let new_folder = self.new_folder.as_ref().map(|row| {
591	            let name = row.input.read(cx).value();
592	            let problem = row.error.clone().map(|err| err.to_string()).or_else(|| {
593	                (!name.is_empty())
594	                    .then(|| new_folder_problem(&self.dir, &name))
595	                    .flatten()
596	            });
597	            let can_create = new_folder_problem(&self.dir, &name).is_none();
598	            let row_element = v_flex()
599	                .id("folder-new-row")
600	                .gap_1()
601	                .px_3()
602	                .py_1()
603	                .child(
604	                    h_flex()
605	                        .gap_2()
606	                        .child(Icon::new(IconName::FolderClosed).text_color(theme.muted_foreground))
607	                        .child(
608	                            div()
609	                                .flex_1()
610	                                .min_w_0()
611	                                .child(Input::new(&row.input).small()),
612	                        )
613	                        .child(
614	                            Button::new("folder-new-create")
615	                                .primary()
616	                                .small()
617	                                .label("Create")
618	                                .disabled(!can_create)
619	                                .on_click(cx.listener(|this, _, window, cx| {
620	                                    this.create_new_folder(window, cx)
621	                                })),
622	                        )
623	                        .child(
624	                            Button::new("folder-new-cancel")
625	                                .ghost()
626	                                .small()
627	                                .icon(IconName::X)
628	                                .tooltip("Don't create a folder")
629	                                .on_click(cx.listener(|this, _, window, cx| {
630	                                    this.close_new_folder(window, cx)
631	                                })),
632	                        ),
633	                )
634	                .when_some(problem, |row, problem| {
635	                    row.child(
636	                        div()
637	                            .pl_6()
638	                            .text_xs()
639	                            .text_color(theme.danger)
640	                            .child(problem),
641	                    )
642	                });
643	            // Lets UI tests find the row; inert in normal builds.
644	            gpui_kit::TestSupportExt::test_support(row_element)
645	        });
646	        let rows = folders.iter().enumerate().map(|(ix, folder)| {
647	            let name = folder
648	                .file_name()
649	                .map(|name| name.to_string_lossy().into_owned())
650	                .unwrap_or_default();
651	            let selected = self.selected == Some(ix);
652	            let row = h_flex()
653	                .id(("folder-row", ix))
654	                .gap_2()
655	                .px_3()
656	                .py_1()
657	                .rounded(theme.radius)
658	                .cursor_pointer()
659	                .when(selected, |row| {
660	                    row.bg(theme.list_active)
661	                        .text_color(theme.accent_foreground)
662	                })
663	                .when(!selected, |row| row.hover(|row| row.bg(theme.list_hover)))
664	                .on_click(cx.listener(move |this, event: &ClickEvent, _, cx| {
665	                    this.click_folder(ix, event.click_count(), cx)
666	                }))
667	                .child(Icon::new(IconName::FolderClosed).text_color(theme.muted_foreground))
668	                .child(div().min_w_0().truncate().child(name));
669	            // Lets UI tests find the row; inert in normal builds.
670	            gpui_kit::TestSupportExt::test_support(row)
671	        });
672	        // The rows are the list's own children, so a folder's index is the
673	        // item to scroll to.
674	        let list = v_flex()
675	            .id("folder-list")
676	            .size_full()
677	            .overflow_y_scroll()
678	            .track_scroll(&self.scroll)
679	            .p_2()
680	            .children(new_folder)
681	            .children(rows);
682	        div()
