708	            .on_action(cx.listener(|this, _: &SelectPrevious, _, cx| this.step(-1, cx)))
709	            .on_action(cx.listener(|this, _: &SelectFirst, _, cx| this.select_end(false, cx)))
710	            .on_action(cx.listener(|this, _: &SelectLast, _, cx| this.select_end(true, cx)))
711	            .on_action(cx.listener(|this, _: &SelectPageDown, _, cx| this.step(PAGE as isize, cx)))
712	            .on_action(cx.listener(|this, _: &SelectPageUp, _, cx| this.step(-(PAGE as isize), cx)))
713	            .on_action(cx.listener(|this, _: &OpenSelected, _, cx| this.open_selected(cx)))
714	            .on_action(cx.listener(|this, _: &GoUp, _, cx| this.up(cx)))
715	            .on_action(cx.listener(|this, _: &GoHome, _, cx| this.go(home(), cx)))
716	            .on_action(cx.listener(|this, _: &ChooseFolderAction, _, cx| {
717	                cx.emit(ChooseFolder(this.choice()))
718	            }))
719	            .on_action(cx.listener(|this, _: &ToggleHidden, _, cx| {
720	                this.set_show_hidden(!this.show_hidden, cx)
721	            }))
722	            .on_action(cx.listener(|this, _: &NewFolderAction, window, cx| {
723	                if this.folders.is_ok() {
