725	                }
726	            }))
727	            // The window's Esc, which outranks any other, closes the new
728	            // folder row first.
729	            .on_action(cx.listener(|this, _: &FocusChat, window, cx| this.escape(window, cx)))
730	            // The name field's own Escape, passed up once it has nothing to
731	            // cancel itself.
732	            .on_action(cx.listener(|this, _: &Escape, window, cx| this.escape(window, cx)))
733	            .size_full()
734	            .child(
735	                div()
