743	            .child(self.render_bar(cx))
744	            .child(
745	                v_flex()
746	                    .id("folder-list-area")
747	                    .flex_1()
748	                    .min_h_0()
749	                    .track_focus(&self.focus_handle)
750	                    .child(self.render_folders(cx)),
751	            )
752	            .child(
753	                h_flex()
754	                    .gap_2()
755	                    .px_4()
756	                    .py_3()
757	                    .border_t_1()
758	                    .border_color(border)
759	                    .child(
760	                        div()
761	                            .flex_1()
762	                            .min_w_0()
763	                            .truncate()
764	                            .text_sm()
765	                            .text_color(muted)
766	                            .child(choice.display().to_string()),
767	                    )
768	                    .child(
769	                        Button::new("folder-cancel")
