            Browse::Folder => false,
            Browse::File(None) => true,
            Browse::File(Some(name)) => name_of(&entry.path) == *name,
        })
        .collect();
    entries.sort_by_key(|entry| (!entry.is_dir, name_of(&entry.path).to_lowercase()));
