            assert!(window.try_find(("folder-row", 1usize)).is_none(), "notes.md is listed");
            window.double_click(("folder-row", 0usize), cx);
        })
        .unwrap();
        cx.run_until_parked();
        assert_eq!(cx.update(|cx| ProjectDirectory::get(cx)), Some(base.join("demo")));
        assert!(!main.read_with(cx, |main, _| main.panel_open()), "the panel stayed open");
        std::fs::remove_dir_all(&base).ok();
